```python
def __setitem__(self, key, value):
    value = extract_array(value, extract_numpy=True)

    if not lib.is_scalar(key) and is_list_like(key):
        key = np.asarray(key)

    if not lib.is_scalar(value):
        value = np.asarray(value)

    values = self._ndarray
    if values.dtype.kind in ['O', 'U']:  # Object or Unicode type
        values[key] = value
    else:
        try:
            # Attempt to cast only if it's a compatible type, otherwise let it raise ValueError
            values[key] = value
        except (ValueError, TypeError):
            raise ValueError(f"Cannot set value of type {type(value).__name__} in array of type {values.dtype.name}")
